async function settleOrStall(promise, timeoutMs = 200) {
  let timer;
  const watchdog = new Promise((resolve) => {
    timer = setTimeout(() => resolve("did not settle"), timeoutMs);
  });
  try {
    return await Promise.race([promise, watchdog]);
  } finally {
    if (timer) clearTimeout(timer);
  }
}
const RECORDING_RATE = 48e3;
function makeFrame(durationMs, sampleRate = RECORDING_RATE, channels = 1) {
  const samplesPerChannel = Math.floor(durationMs / 1e3 * sampleRate);
  return new AudioFrame(
    new Int16Array(samplesPerChannel * channels),
    sampleRate,
    channels,
    samplesPerChannel
  );
}
function frameDurationMs(frame) {
  return frame.samplesPerChannel / frame.sampleRate * 1e3;
}
function makeToneFrame(durationMs, sampleRate = RECORDING_RATE) {
  const samplesPerChannel = Math.floor(durationMs / 1e3 * sampleRate);
  const data = new Int16Array(samplesPerChannel);
  for (let i = 0; i < samplesPerChannel; i++) {
    data[i] = Math.round(8e3 * Math.sin(2 * Math.PI * 1e3 * i / sampleRate));
  }
  return new AudioFrame(data, sampleRate, 1, samplesPerChannel);
}
