    const finishes = [];
    output.on(AudioOutput.EVENT_PLAYBACK_FINISHED, (event2) => {
      finishes.push(event2);
    });
    downstream.onFinishForwarded = () => {
      expect(finishes).toHaveLength(0);
    };
    await output.captureFrame(makeFrame(20, 24e3));
    await output.captureFrame(makeFrame(20, 24e3));
    output.flush();
    const event = await output.waitForPlayout();
    expect(finishes).toHaveLength(1);
