    output.flush();
    await new Promise((resolve) => setTimeout(resolve, 5));
    downstream.onPlaybackFinished({ playbackPosition: 1e-3, interrupted: false });
    downstream.onPlaybackFinished({ playbackPosition: 1e-3, interrupted: false });
